# ---- ResetTail ---------------------------------------------------------------
# a `ret` after Reset's last jmp: the compiler's epilogue, never reached
# no caller: unreferenced code
ResetTail:
    ret     0, 0

# ---- NmiHandler --------------------------------------------------------------
# sets P04 bit 3, then CPUM bit 4 over and over ([INFERENCE] STOP mode): never returns
NmiHandler:
    add     -4, sp
    bset    0x08, (P04)
    setlb
    movhu   (CPUM), d0
    or      0x10, d0
    movhu   d0, (CPUM)
    lra
    retf    0, 4

# ============================== the program image, run in work RAM at 0x50000010 ============
