    beq     loc_5000C262
    mov     0x0000aaaa, d1
    cmp     2, d0
    beq     loc_5000C262
    mov     0x0000ffff, d1
    cmp     3, d0
    beq     loc_5000C262
    clr     d1
loc_5000C262:
    mov     0, a1
    setlb
    mov     LCDC_VRAM, a2
    mov     a1, a0
    add     a0, a0
    mov     a0, d0
    movhu   d1, (d0, a2)
    inc     a1
    cmp     0x25800, a1
    lcs
    retf    [a2], 4

